// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0)); // owner is unset (address(0)); admissible callers are non-owners
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Rule: a non-owner can never execute owned(); it must revert for every caller.
        assertTrue(!ok);
    }
}
